<script setup lang="ts">
import { ref } from 'vue'
import type { PerformanceLevel } from '@englishflow/performance'
export type MobileQuestion = { id: string; type: 'CHOICE' | 'FILL_BLANK' | 'DRAG_SORTER' | 'LISTEN' | 'TRANSLATION'; prompt: string; sentence?: string; sourceText?: string; audioUrl?: string | null; options?: Array<{ key: string; text: string }>; tokens?: Array<{ tokenId: string; text: string }> }
defineProps<{ question: MobileQuestion; disabled?: boolean; performanceLevel: PerformanceLevel }>()
const emit = defineEmits<{ answer: [value: unknown] }>()
const selected = ref<string | null>(null); const translation = ref(''); const ordered = ref<string[]>([]); const playing = ref(false)
function choose(value: string): void { selected.value = value; emit('answer', value) }
function toggleToken(tokenId: string): void { ordered.value = ordered.value.includes(tokenId) ? ordered.value.filter((id) => id !== tokenId) : [...ordered.value, tokenId]; emit('answer', ordered.value) }
</script>
<template><view class="question-card"><text class="prompt">{{ question.prompt }}</text><text v-if="question.type === 'FILL_BLANK' && question.sentence" class="sentence">{{ question.sentence }}</text><text v-if="question.type === 'TRANSLATION' && question.sourceText" class="sentence">{{ question.sourceText }}</text><button tabindex="0" role="button" v-if="question.type === 'LISTEN'" class="audio" type="button" :disabled="!question.audioUrl" @click="playing = !playing">{{ question.audioUrl ? (playing ? 'Ⅱ 播放中' : '▶ 播放音频') : '音频不可用' }}</button><text v-if="question.type === 'LISTEN' && !question.audioUrl" class="notice">服务端未返回音频资源，未伪造播放成功。</text><view v-if="question.type === 'DRAG_SORTER'" class="tokens"><button tabindex="0" role="button" v-for="token in question.tokens ?? []" :key="token.tokenId" class="token" type="button" :disabled="disabled" :class="{ 'token--selected': ordered.includes(token.tokenId) }" @click="toggleToken(token.tokenId)">{{ token.text }}</button></view><view v-else-if="question.type === 'TRANSLATION'" class="translation"><textarea v-model="translation" :disabled="disabled" placeholder="输入你的译文" @blur="emit('answer', translation)" /><button tabindex="0" role="button" class="submit" type="button" :disabled="disabled || !translation.trim()" @click="emit('answer', translation)">提交译文</button></view><view v-else class="options"><button tabindex="0" role="button" v-for="option in question.options ?? []" :key="option.key" class="option" :class="{ 'option--selected': selected === option.key }" type="button" :disabled="disabled" @click="choose(option.key)">{{ option.key }} · {{ option.text }}</button></view></view></template>
<style scoped lang="scss">.question-card{display:grid;gap:22rpx;padding:24rpx;border:1rpx solid var(--yx-border);border-radius:20rpx;background:var(--yx-surface-card)}.prompt{font-size:34rpx;font-weight:750;line-height:1.45}.sentence{padding:18rpx;border-radius:14rpx;color:var(--yx-brand);background:var(--yx-brand-soft);font-size:28rpx;line-height:1.6}.audio,.submit{min-height:88rpx;border:0;border-radius:16rpx;color:var(--yx-on-brand);background:var(--yx-action);font-size:28rpx;font-weight:700}.audio:disabled{color:var(--yx-text-secondary);background:var(--yx-surface-page)}.notice{padding:16rpx;border-radius:12rpx;color:var(--yx-warning);background:var(--yx-danger-soft);font-size:22rpx}.options,.tokens{display:grid;gap:12rpx}.option,.token{min-height:88rpx;padding:0 18rpx;border:1rpx solid var(--yx-border);border-radius:14rpx;color:var(--yx-text-primary);background:var(--yx-surface-card);text-align:left;font-size:25rpx}.option--selected,.token--selected{border-color:var(--yx-brand);color:var(--yx-brand);background:var(--yx-brand-soft)}.translation{display:grid;gap:12rpx}textarea{width:100%;padding:18rpx;border:1rpx solid var(--yx-border);border-radius:14rpx;box-sizing:border-box;font-size:26rpx;line-height:1.6}</style>
